import { readdirSync, readFileSync } from "node:fs";
import { join, relative } from "node:path";

import { describe, expect, it } from "vitest";

// This file lives under features/profile/ and is itself walked by AC-1, so the
// needles are built from fragments: no line here holds either phrase literally.
const STALE_PHRASE = ["multi-workspace", "support"].join(" ");
const TASK_MARKER = "TO" + "DO";
const ORG_ID_WORD = "organization" + "Id";

const PROFILE_ROOT = join(process.cwd(), "features", "profile");
const PROFILE_SERVICE = join(PROFILE_ROOT, "services", "get-profile.ts");
const EXPORT_LINE = "export async function getProfileData";

function listFiles(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) return listFiles(path);
    return entry.isFile() ? [path] : [];
  });
}

function docCommentAbove(source: string, marker: string): string | null {
  const exportIndex = source.indexOf(marker);
  if (exportIndex === -1) return null;
  const before = source.slice(0, exportIndex);
  const trimmed = before.trimEnd();
  if (!trimmed.endsWith("*/")) return null;
  const open = trimmed.lastIndexOf("/**");
  if (open === -1) return null;
  return trimmed.slice(open, trimmed.length);
}

function commentText(block: string): string {
  return block
    .replace(/^\/\*\*/, "")
    .replace(/\*\/$/, "")
    .split("\n")
    .map((line) => line.replace(/^\s*\*\s?/, ""))
    .join(" ")
    .replace(/\s+/g, " ")
    .trim();
}

describe("getProfileData doc comment (profile-todo-cleanup)", () => {
  it("AC-1: no profile file mentions the stale workspace note or a task marker beside the org id word", () => {
    const files = listFiles(PROFILE_ROOT);
    expect(files.length).toBeGreaterThan(0);

    const filesWithPhrase: string[] = [];
    const linesWithBoth: string[] = [];

    for (const file of files) {
      const text = readFileSync(file, "utf8");
      const rel = relative(process.cwd(), file);
      if (text.includes(STALE_PHRASE)) filesWithPhrase.push(rel);
      text.split("\n").forEach((line, index) => {
        if (line.includes(TASK_MARKER) && line.includes(ORG_ID_WORD)) {
          linesWithBoth.push(`${rel}:${index + 1}`);
        }
      });
    }

    expect(filesWithPhrase).toEqual([]);
    expect(linesWithBoth).toEqual([]);
  });

  it("AC-2: the comment above getProfileData says the profile is per person and takes no organization id", () => {
    const source = readFileSync(PROFILE_SERVICE, "utf8");
    const block = docCommentAbove(source, EXPORT_LINE);

    expect(block).not.toBeNull();
    const text = commentText(block ?? "");

    expect(text).toMatch(/the profile is per person, not per workspace/i);
    expect(text).toMatch(/`?getProfileData`? takes no organization id/i);
  });
});

