import { beforeEach, describe, expect, it, vi } from "vitest";

// The same mocks as the existing get-profile suite: only the user and
// user_profiles tables exist, and the env flag is switchable per test.
const tables = vi.hoisted(() => ({
  user: { id: "user.id", name: "user.name", email: "user.email" },
  userProfiles: { userId: "userProfiles.userId" },
}));

const envMock = vi.hoisted(() => ({
  NEXT_PUBLIC_E2E_MSW: undefined as "enabled" | undefined,
}));

const dbSelectMock = vi.hoisted(() =>
  vi.fn(() => ({
    from: () => ({
      where: () => ({ limit: () => Promise.resolve([]) }),
    }),
  })),
);

vi.mock("@/env", () => ({
  E2E_MSW_ENABLED: "enabled",
  env: envMock,
}));

vi.mock("@/shared/lib/db/client", () => ({
  db: {
    select: dbSelectMock,
  },
}));

vi.mock("@/shared/lib/db/schema", () => tables);

vi.mock("@/shared/lib/logger", () => ({
  createLogger: () => ({
    info: vi.fn(),
    error: vi.fn(),
    warn: vi.fn(),
    debug: vi.fn(),
  }),
}));

describe("getProfileData signature (profile-todo-cleanup)", () => {
  beforeEach(() => {
    envMock.NEXT_PUBLIC_E2E_MSW = undefined;
    dbSelectMock.mockClear();
  });

  it("AC-3: still takes exactly one parameter and returns the E2E fixture without the database", async () => {
    const { getProfileData } = await import("../get-profile");

    expect(getProfileData.length).toBe(1);

    envMock.NEXT_PUBLIC_E2E_MSW = "enabled";
    const result = await getProfileData("user-ac3");

    expect(result).toEqual({
      personal: {
        fullName: "Development User",
        email: "<email>",
        avatarUrl: null,
      },
    });
    expect(dbSelectMock).not.toHaveBeenCalled();
  });
});
